if(!UnityEditor.EditorApplication.isPlaying)throw new System.Exception("Play required");
var runtime=UnityEngine.Object.FindFirstObjectByType<EchoSphere.Runtime.EchoSphereRuntime>();var ui=UnityEngine.Object.FindFirstObjectByType<EchoSphere.Presentation.SourceUiDocument>();var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
if(!(bool)runtime.GetType().GetField("_userPaused",flags).GetValue(runtime))throw new System.Exception("Paused actual saved run required");
var model=runtime.ReadNativePauseStatsState();var root=(EchoSphere.Presentation.VisualCssNode)ui.GetType().GetField("_root",flags).GetValue(ui);
System.Collections.Generic.IEnumerable<EchoSphere.Presentation.VisualCssNode> Nodes(EchoSphere.Presentation.VisualCssNode n){yield return n;foreach(var child in n.Children)foreach(var sub in Nodes(child))yield return sub;}
string Text(EchoSphere.Presentation.VisualCssNode n)=>n.Tag=="#text"?n.Text:string.Concat(n.Children.Where(c=>c.Pseudo==null).Select(Text));
var boxes=Nodes(root).Where(n=>n.Attribute("className")=="rounded-xl bg-[#0d1726] border border-[#243b55] px-3 py-2").ToArray();if(boxes.Length!=model.Stats.Count)throw new System.Exception("Actual pause stats not ready");int checks=1;for(int i=0;i<boxes.Length;i++){var children=boxes[i].Children.Where(c=>c.Pseudo==null&&c.Tag!="#text").ToArray();checks+=2;if(model.Stats[i].Label!=Text(children[0])||model.Stats[i].Value!=Text(children[1]))throw new System.Exception("Actual saved-scene stat differs "+i);}
var result=Newtonsoft.Json.JsonConvert.SerializeObject(new{status="PASS typed pause reader / actual saved-run pause UI",checks,stats=model.Stats.Count,spheres=model.Spheres.Count,liveCards=model.Spheres.Count(s=>s.OnField),nativeHudDefault=runtime.UsesNativeHud,limits="Real Editor display-reader validation only; native pause view not enabled; no formulas/RNG/settings changed"});UnityEditor.SessionState.SetString("EchoNativePauseStatsLive",result);System.IO.File.WriteAllText(System.IO.Path.Combine(UnityEngine.Application.dataPath,"../Temp/native-pause-stats-live-evidence.json"),result);return result;
